import {TIERS,WALL_SIZE,TOTAL_PIXELS,STORAGE_KEY,freshState,stats,money,minimumBid,safeUrl,validateAd,reserve,cancelReservation,startAuction,placeBid,expire,simulatePayment,submitAd,approveAd,rejectAd,estimateRevenue} from './model.mjs';

const $=s=>document.querySelector(s), main=$('#main-content'), modal=$('#modal');
let state=freshState(),zoom=1,wallFilter='all',directoryFilter='all',search='',uploadedImage=null,toastTimer;
let checkoutLot=null,returnAction=null,activeDialog=null,afterNavigation=null;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=()=>location.hash.slice(1).split('?')[0]||'wall';
const amount=n=>escape(money(n));
const statusText=s=>({'available':'Available','upcoming':'Auction queue','active':'Bidding open','reserved':'In checkout','awaiting-payment':'Winner payment pending','paid':'Ready for your ad','review':'Ad in review','published':'On the wall','hidden':'Ad hidden'}[s]||s);
const pill=(s,c='')=>`<span class="chip ${c}">${escape(s)}</span>`;
const action=(label,act,id='',cls='')=>`<button class="button ${cls}" data-action="${act}" ${id?`data-id="${escape(id)}"`:''}>${label}</button>`;
const ago=t=>{const m=Math.max(0,Math.floor((Date.now()-t)/60000));return m<1?'just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`;};
const remaining=t=>{const s=Math.max(0,Math.ceil((t-Date.now())/1000));return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{toast('Browser storage is full. Remove a large image or reset the demo.');return false;}}
function load(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY));if(s?.version===1&&s.lots?.length===940&&Array.isArray(s.events)&&Array.isArray(s.reports)){state=s;expire(state);}}catch{state=freshState();}}
load();
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function find(id){const l=state.lots.find(l=>l.id===id);if(!l)throw Error('Block not found.');return l;}
function run(fn){try{return fn();}catch(e){toast(e.message);return null;}}
function commit(message){save();render();if(message)toast(message);}
function modalOpen(label,content,type='info'){activeDialog=type;$('#dialog-label').textContent=label;$('#modal-body').innerHTML=content;if(!modal.open)modal.showModal();}
function modalClose(){if(checkoutLot){cancelReservation(state,checkoutLot);checkoutLot=null;save();render();}modal.close();activeDialog=null;}
$('#close-modal').onclick=modalClose;
modal.addEventListener('cancel',e=>{e.preventDefault();modalClose();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modalClose();}});
window.addEventListener('hashchange',()=>{modalClose();render();window.scrollTo({top:0,behavior:'instant'});const next=afterNavigation;afterNavigation=null;next?.();});
$('#profile-button').onclick=()=>profileDialog();
$('#reset-demo').onclick=()=>modalOpen('RESET THIS BROWSER',`<h2 id="modal-title">A fresh canvas?</h2><p>This clears this browser’s demo profiles, bids, ads and simulated purchases. Your existing website and Firebase data are unaffected.</p><div class="dialog-actions">${action('Keep exploring','close','','ghost')}${action('Reset demo','reset-confirm','','dark')}</div>`);

function profileDialog(after){returnAction=after||null;modalOpen('DEMO PROFILE',`<h2 id="modal-title">Hello, internet person.</h2><p>Create a local profile to try buying a block, bidding and publishing an ad. This preview does not create a real account or collect an email address.</p><form id="profile-form"><div class="form-group"><label for="profile-name">YOUR DISPLAY NAME</label><input id="profile-name" name="name" minlength="2" maxlength="24" required autocomplete="nickname" placeholder="e.g. Studio Luna" value="${escape(state.user?.name||'')}"></div><button class="button dark full" type="submit">${state.user?'Update demo profile':'Create demo profile'} ↗</button></form><div class="notice blue">For review: switch between two test bidders to try a competitive auction.</div><div class="profile-choices">${action('Try as Alex','switch-user','alex','small ghost')}${action('Try as Sam','switch-user','sam','small ghost')}${state.user?action('Sign out locally','sign-out','','small ghost'):''}</div>`,'profile');}
function loginThen(fn){if(state.user)fn();else profileDialog(fn);}
function headerUpdate(){const owned=state.user?state.lots.filter(l=>l.owner===state.user.id).length:0;const wins=state.user?state.lots.filter(l=>l.status==='awaiting-payment'&&l.winner===state.user.id).length:0;$('#profile-button').textContent=state.user?`${state.user.name} ↗`:'Join the wall ↗';$('#notification-count').hidden=!wins;$('#notification-count').textContent=wins;document.querySelectorAll('[data-route]').forEach(a=>{const selected=a.dataset.route===route();a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function metrics(){const s=stats(state);return `<div class="metrics"><div class="metric"><div class="metric-label">THE WALL IS FILLING</div><div class="metric-value">${s.percent.toFixed(2)}<span style="font-size:16px">%</span></div><div class="progress" role="progressbar" aria-label="Demo paid pixel area" aria-valuenow="${s.percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${s.percent}%"></span></div><small>${s.paidPixels.toLocaleString()} / 1,000,000 pixels · demo</small></div><div class="metric"><div class="metric-label">CORNERS CLAIMED</div><div class="metric-value">${s.paidLots}<span class="muted" style="font-size:16px"> / 940</span></div><small>Simulated paid blocks only</small></div><div class="metric"><div class="metric-label">COLLECTED · DEMO</div><div class="metric-value">${amount(s.gross)}</div><small>Gross sales, before costs</small></div><div class="metric"><div class="metric-label">THE DAILY CHALLENGE</div><div class="metric-value">${state.campaignStart?`Day ${Math.floor((Date.now()-state.campaignStart)/86400000)+1}`:'Day zero'}</div><small>${state.campaignStart?'Fill the wall. Tell the story.':'The first paid block starts the clock.'}</small></div></div>`;}
function tierCards(){return `<div class="tier-grid">${Object.entries(TIERS).map(([key,t])=>`<article class="tier-card" style="--tier-bg:${t.color}"><div class="tier-top">${pill(t.mode==='auction'?'FEATURED AUCTION':'BUY NOW') }<span class="tier-symbol">${t.side}²</span></div><h3>${t.name}</h3><p>${t.description}</p><div class="tier-price">${t.mode==='auction'?'<span style="font-size:13px">FROM </span>':''}${amount(t.price)}</div><small>${t.side} × ${t.side} pixels · 12 months from payment</small><ul><li>${key==='brand'?'16× a community block':key==='creator'?'4× a community block':'625 pixels, all yours'}</li><li>Image, link & discover profile</li><li>${key==='brand'?'Featured auction listing':'One payment, no subscription'}</li></ul>${action(key==='brand'?'Explore brand auctions ↗':`Pick a ${key} spot ↗`,key==='brand'?'go-auctions':'pick-tier',key,'full '+(key==='brand'?'dark':''))}</article>`).join('')}</div>`;}
function activeAuction(){return state.lots.find(l=>l.status==='active'||l.status==='awaiting-payment');}
function featureCard(){const a=activeAuction();return `<article class="feature-card"><div class="eyebrow">THE BIG SPOT</div><h2>A little competition.<br>A lot more room.</h2><p>100 × 100 pixels for a brand with something to say.</p><div class="feature-art"><span class="block-label">YOUR BRAND<br>GOES HERE ↗</span></div><div class="countdown"><div><small>${a?.bids.length?'CURRENT BID':'STARTING AT'}</small><br><strong>${amount(a?.amount||500)}</strong></div><div><small>${a?.status==='active'?'ENDS IN':a?'PAYMENT':'NEXT DROP'}</small><br><strong ${a?.status==='active'?`data-countdown="${a.endsAt}"`:''}>${a?.status==='active'?remaining(a.endsAt):a?'PENDING':'SOON'}</strong></div></div><a class="button lime full" href="#auctions">${a?'View the auction':'Explore the auction'} ↗</a><p style="font-size:10px;margin-top:12px">One featured auction at a time. No charge to bid.</p></article>`;}
function wallPage(){return `<section class="hero"><div><div class="eyebrow">THE INTERNET IS BETTER WITH YOU IN IT</div><h1>A little space.<br>A <span class="italic">big</span> internet.</h1></div><div class="hero-copy"><p>One million pixels. A growing collection of people, projects and big ideas. Claim a little corner, or bid for a bigger one.</p><div class="hero-actions"><a class="button dark" href="#plans">Find your spot ↗</a><span class="scribble">every square has a story.</span></div></div></section>${metrics()}<div class="wall-layout"><section><div class="window"><div class="window-bar"><span>▦</span><span class="grow">THE MILLION PIXEL WALL</span><span>1000 × 1000</span><span class="window-controls" aria-hidden="true"><i></i><i></i></span></div><div class="wall-toolbar">${['all','community','creator','brand'].map(f=>`<button class="tab ${wallFilter===f?'active':''}" data-action="wall-filter" data-id="${f}" aria-pressed="${wallFilter===f}">${f==='all'?'All spots':TIERS[f].name}</button>`).join('')}<span class="toolbar-spacer"></span><button class="icon-button" data-action="zoom-out" aria-label="Zoom out">−</button><span class="zoom-label">${Math.round(zoom*100)}%</span><button class="icon-button" data-action="zoom-in" aria-label="Zoom in">+</button></div><div class="wall-scroll" id="wall-scroll"><div class="wall-canvas" id="wall-canvas" role="group" aria-label="Interactive one million pixel wall"></div></div><div class="wall-bottom"><span class="legend" style="--c:#edf4d4"><i></i>Community · 25 × 25</span><span class="legend" style="--c:#dce7ff"><i></i>Creator · 50 × 50</span><span class="legend" style="--c:#f7dae8"><i></i>Brand · 100 × 100</span><span class="legend" style="--c:#2935a3"><i></i>Claimed</span></div></div><div class="wall-caption"><span>Click a square to meet its owner or make it yours.</span><a href="#directory">Prefer a readable list? ↗</a></div></section><aside class="side-stack">${featureCard()}<article class="note-card"><div class="eyebrow">BUILT IN PUBLIC</div><h3>Watch a million<br>pixels become a story.</h3><p>A daily update. A fuller canvas. A new internet neighbor. Follow the wall as it grows.</p><a href="#journey">Open the progress journal ↗</a></article><article class="note-card pink"><div class="eyebrow">SMALL BUT MIGHTY</div><h3>No invisible pixels.</h3><p>Every claimed block gets its own readable profile in Discover. Zoom in on the wall, or explore at your own pace.</p></article></aside></div><section id="plans"><div class="section-heading"><div><div class="eyebrow">ROOM FOR EVERY KIND OF IDEA</div><h2>Pick your piece of the internet.</h2></div><p>Own your placement for 12 months. Prices are in AED. No recurring billing. All prices shown here are a proposed launch model.</p></div>${tierCards()}</section><div class="lower-grid"><section class="activity"><h3>Around the wall</h3>${activityList(4)}</section><section class="activity"><h3>Good neighbors, by design.</h3><p class="muted" style="font-size:13px">Ads are reviewed before publication. Winners have a payment deadline. Bids never count as revenue. No resale speculation or promises of clicks.</p><a href="#rules" class="button small ghost" style="margin-top:20px">Read the wall rules ↗</a></section></div>`;}
function paintWall(){const wall=$('#wall-canvas');if(!wall)return;wall.style.width=`${zoom*100}%`;wall.innerHTML=state.lots.map(l=>{const t=TIERS[l.tier],ad=l.status==='published'?l.ad:null,dim=wallFilter!=='all'&&wallFilter!==l.tier,cl=ad?'':l.status==='active'?'active-lot':l.paidAt?'paid-empty':l.tier==='brand'?'brand-empty':'';const text=ad?ad.title:l.status==='active'?'BID ↗':l.paidAt?'✓':l.tier==='brand'?'BRAND':'';return `<button class="pixel ${cl} ${dim?'is-dim':''}" data-action="lot" data-id="${l.id}" style="left:${l.x/10}%;top:${l.y/10}%;width:${l.side/10}%;height:${l.side/10}%;--tier-bg:${ad?.color||t.color};${ad?`background:${ad.color};color:${contrast(ad.color)}`:''}" title="${escape(`${ad?.title||t.name} · ${l.side} × ${l.side} · ${statusText(l.status)} · ${money(l.amount)}`)}" aria-label="${escape(`${l.id}: ${ad?.title||t.name}, ${l.side} by ${l.side} pixels, ${statusText(l.status)}, ${money(l.amount)}`)}">${ad?.image?`<img src="${ad.image}" alt="" loading="lazy">`:`<span class="pixel-name">${escape(text)}</span>${l.tier==='brand'&&!ad&&!l.paidAt?`<span>${l.status==='active'?amount(l.amount):'100 × 100'}</span>`:''}`}</button>`;}).join('');}
function contrast(hex){const rgb=hex.slice(1).match(/../g).map(n=>parseInt(n,16));return (rgb[0]*.299+rgb[1]*.587+rgb[2]*.114)>155?'#20265e':'#ffffff';}
function activityList(limit){return state.events.length?state.events.slice(0,limit).map(e=>`<div class="activity-row"><span>${escape(e.message)}</span><time>${ago(e.at)}</time></div>`).join(''):'<div class="empty"><div class="empty-symbol">[ 0 → 1 ]</div><p>The first corner is waiting for its story. Try a demo purchase to see the wall come alive.</p></div>';}
function pageHead(kicker,title,copy,extra=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div>${extra}</div>`;}
function auctionsPage(){const a=activeAuction(),next=state.lots.find(l=>l.tier==='brand'&&l.status==='upcoming');return `${pageHead('BIGGER SPOTS. A LITTLE FRIENDLY RIVALRY.','The big spot auction.','One featured brand block at a time, so every auction gets a moment. A 100 × 100 placement plus a readable Discover profile.') }<div class="notice blue">Review edition: bids and checkout are simulated. Live auctions open only after a supported payment account and secure backend are connected.</div><section class="content-card"><div class="auction-layout"><div class="auction-preview"><span class="chip pink">${a?'FEATURED BLOCK':'NEXT FEATURED BLOCK'}</span><strong>100 × 100</strong><span>PIXELS FOR YOUR NEXT BIG THING</span><small>16× a community block · 12-month placement</small></div><div class="auction-details">${pill(a?statusText(a.status):'COMING SOON',a?.status==='active'?'lime':'pink')}<h2 style="margin-top:18px">The next name<br>on the wall could be yours.</h2><p>No bidding fees. Whole-dirham bids. At least a 10% increase after the opening bid. A last-minute bid extends the timer by up to 60 seconds, capped at 10 extra minutes.</p><div class="timer-box"><div><small>${a?.bids.length?'CURRENT BID':'OPENING BID'}</small><strong>${amount(a?.amount||500)}</strong></div><div><small>${a?.status==='active'?'ENDS IN':a?'PAYMENT STATUS':'DURATION'}</small><strong ${a?.status==='active'?`data-countdown="${a.endsAt}"`:''}>${a?.status==='active'?remaining(a.endsAt):a?'PENDING':'48 HOURS'}</strong></div></div>${a?.status==='active'?`${action('Place a demo bid ↗','bid',a.id,'dark')}<p>Current leader: <strong>${escape(a.bids.at(-1)?.name||'No bids yet')}</strong> · ${a.bids.length} bids</p>`:a?.status==='awaiting-payment'?`<p>The winner has 24 hours to finish checkout. This block is not sold until payment is confirmed.</p>${a.winner===state.user?.id?action('Complete demo checkout ↗','pay-winner',a.id,'dark'):''}`:`${action('Try the featured auction ↗','start-demo',next?.id||'','dark')}<p style="font-size:11px">Starts a local 48-hour sample auction in this browser.</p>`}</div></div></section><div class="two-col" style="margin-top:24px"><section class="content-card"><h3>Bid history</h3>${a?.bids.length?[...a.bids].reverse().map(b=>`<div class="bid-history"><span>${escape(b.name)}</span><strong>${amount(b.amount)}</strong><span class="muted">${ago(b.at)}</span></div>`).join(''):'<p>No bids yet. The first bid can be the opening price.</p>'}</section><section class="content-card"><h3>What happens if I win?</h3><ol><li>Your block is reserved for 24 hours.</li><li>Complete checkout from My Pixels.</li><li>Upload an image and link for review.</li><li>Your ad appears after approval.</li></ol><p>A missed payment returns the block to the queue. No surprise automatic charges and no automatic charge to the runner-up.</p><a href="#rules">Read the full rules ↗</a></section></div><div class="section-heading"><div><div class="eyebrow">20 BRAND PLACEMENTS IN TOTAL</div><h2>More room, coming up.</h2></div><p>Auctions run in a clear queue. No invented competing bids or artificial activity.</p></div><div class="card-grid">${state.lots.filter(l=>l.tier==='brand'&&l.status==='upcoming').slice(0,6).map((l,i)=>`<article class="tier-card" style="--tier-bg:#f7e5ec">${pill('IN THE QUEUE')}<h3>Brand block ${escape(l.id)}</h3><p>100 × 100 pixels. Opening at ${amount(500)}.</p>${action('Inspect placement ↗','lot',l.id,'small ghost')}</article>`).join('')||'<p>All brand blocks have been claimed or are in progress.</p>'}</div>`;}
function directoryPage(){return `${pageHead('THE PEOPLE BEHIND THE PIXELS','Discover your next favorite.','Readable profiles for every published ad. Small spots on the wall get a proper introduction here.') }<div class="filter-row"><input id="directory-search" class="search-input" type="search" placeholder="Search projects, people and ideas…" aria-label="Search advertisers" value="${escape(search)}">${['all','community','creator','brand'].map(f=>`<button class="tab ${directoryFilter===f?'active':''}" data-action="directory-filter" data-id="${f}" aria-pressed="${directoryFilter===f}">${f==='all'?'Everyone':TIERS[f].name}</button>`).join('')}</div><div id="directory-results"></div>`;}
function directoryResults(){const out=$('#directory-results');if(!out)return;const matches=state.lots.filter(l=>l.status==='published'&&l.ad&&(directoryFilter==='all'||l.tier===directoryFilter)&&`${l.ad.title} ${l.ad.description} ${l.ownerName}`.toLowerCase().includes(search.toLowerCase()));out.innerHTML=matches.length?`<div class="card-grid">${matches.map(l=>`<article class="ad-card"><div class="ad-image" style="background:${l.ad.color};color:${contrast(l.ad.color)}">${l.ad.image?`<img src="${l.ad.image}" alt="${escape(l.ad.title)}" loading="lazy">`:escape(l.ad.title.slice(0,16))}</div><div class="ad-card-content">${pill(TIERS[l.tier].name)}<h3>${escape(l.ad.title)}</h3><p>${escape(l.ad.description||'A new neighbor on the wall.')}</p>${action('Meet this project ↗','lot',l.id,'small ghost')}<div style="margin-top:15px;font-size:10px" class="muted">${l.side} × ${l.side} · ${escape(l.ownerName)}</div></div></article>`).join('')}</div>`:`<div class="empty"><div class="empty-symbol">[ hello, world. ]</div><h3>${search?'No matching projects yet.':'Good things start with one.'}</h3><p>${search?'Try another search or a different block size.':'Published profiles will appear here after an ad is approved. Try claiming a demo block, upload your ad, then approve it in the demo studio.'}</p><a href="#wall" class="button dark">Explore the wall ↗</a></div>`;}
function dashboardPage(){if(!state.user)return `${pageHead('YOUR VERY OWN CORNER','Make yourself at home.','Manage your blocks, bids and winning checkouts in one place. You do not have to wait for an email.') }<div class="empty"><h3>A wall profile is all you need.</h3><p>This review version uses a local demo profile. Nothing here creates a real account or charges your card.</p>${action('Create a demo profile ↗','profile','','dark')}</div>`;const u=state.user,owned=state.lots.filter(l=>l.owner===u.id),wins=state.lots.filter(l=>l.status==='awaiting-payment'&&l.winner===u.id),reserved=state.lots.filter(l=>l.status==='reserved'&&l.reservedBy===u.id),bidLots=state.lots.filter(l=>l.bids.some(b=>b.uid===u.id)&&!l.paidAt);return `${pageHead('YOUR PIXELS. YOUR STORY.','Your little corner.','Your claims, bids and checkout reminders—all in one place. Preview activity is stored only in this browser.') }<div class="profile-strip"><span class="profile-avatar">${escape(u.name.slice(0,1).toUpperCase())}</span><div class="grow"><h3>${escape(u.name)}</h3><p>${owned.length} blocks claimed · ${owned.reduce((a,l)=>a+l.side**2,0).toLocaleString()} pixels · local demo profile</p></div>${action('Switch profile','profile','','small ghost')}</div>${wins.map(l=>`<div class="notice pink"><strong>You won ${escape(l.id)} for ${amount(l.amount)}.</strong> Complete checkout within <span data-countdown="${l.deadline}">${remaining(l.deadline)}</span>.<div style="margin-top:12px">${action('Complete demo payment ↗','pay-winner',l.id,'dark small')}</div></div>`).join('')}${reserved.map(l=>`<div class="notice">A checkout for ${escape(l.id)} is reserved until <span data-countdown="${l.deadline}">${remaining(l.deadline)}</span>. ${action('Resume','resume-checkout',l.id,'small ghost')}</div>`).join('')}<div class="section-heading" style="margin-top:25px"><h2>My blocks</h2><a href="#wall">Find another spot ↗</a></div>${owned.length?`<div class="card-grid">${owned.map(l=>`<article class="ad-card"><div class="ad-image" style="background:${l.ad?.color||TIERS[l.tier].color};color:${contrast(l.ad?.color||TIERS[l.tier].color)}">${l.ad?.image?`<img src="${l.ad.image}" alt="">`:escape(l.ad?.title||`${l.side} × ${l.side}`)}</div><div class="ad-card-content">${pill(statusText(l.status),l.status==='published'?'lime':'')}<h3>${escape(l.ad?.title||'Your story starts here.')}</h3><p>${escape(l.id)} · ${TIERS[l.tier].name}<br>Demo paid ${amount(l.amount)} · placement ends ${new Date(l.paidAt+365*86400000).toLocaleDateString('en-GB',{timeZone:'Asia/Dubai'})}</p>${action(l.status==='review'?'Edit submission':'Edit your ad ↗','edit-ad',l.id,'small dark')}${action('View block','lot',l.id,'small ghost')}</div></article>`).join('')}</div>`:`<div class="empty"><h3>Your first piece is waiting.</h3><p>Choose a Community or Creator block on the wall, or place a bid in the featured brand auction.</p><a class="button dark" href="#wall">Find my spot ↗</a></div>`}<div class="section-heading"><h2>My bids</h2></div>${bidLots.length?`<div class="table-wrap"><table class="table"><thead><tr><th>BLOCK</th><th>MY LAST BID</th><th>CURRENT PRICE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${bidLots.map(l=>`<tr><td>${escape(l.id)}</td><td>${amount(l.bids.filter(b=>b.uid===u.id).at(-1).amount)}</td><td>${amount(l.amount)}</td><td>${l.status==='active'?(l.bids.at(-1).uid===u.id?'You are leading':'Outbid'):statusText(l.status)}</td><td>${l.status==='active'?action('View auction','go-auctions','','small ghost'):l.winner===u.id?action('Pay','pay-winner',l.id,'small dark'):'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">You have not placed any bids yet.</p>'}`;}
function journeyPage(){const s=stats(state),day=state.campaignStart?Math.floor((Date.now()-state.campaignStart)/86400000)+1:0;return `${pageHead('A WALL BUILT ONE DAY AT A TIME','Day by day. Pixel by pixel.','A public progress journal for the journey to a full wall. Only confirmed payments fill the progress bar.')}${metrics()}<div class="two-col"><section class="content-card"><h3>The daily update</h3><div class="copy-line" id="daily-copy">Day ${day} of filling the Million Pixel Auction.<br>${s.percent.toFixed(2)}% filled. ${s.paidLots} corners claimed.<br>${s.paidPixels.toLocaleString()} / 1,000,000 pixels.<br>Collected: ${money(s.gross)} gross (demo).<br>Who should claim the next spot?</div>${action('Copy daily update ↗','copy-progress','','dark')}<p>These are sample figures from this browser, not real campaign sales. Use verified live data for your published videos.</p></section><section class="activity"><h3>The latest on the wall</h3>${activityList(12)}</section></div>`;}
function howPage(){return `${pageHead('A SIMPLE IDEA, WITH ROOM TO GROW','A million pixels.<br>A place for you.','The wall is exactly 1,000 × 1,000 pixels. Instead of selling invisible single pixels, we group them into useful spaces.') }<div class="two-col"><section class="content-card">${[['Choose your space','Community blocks are 25 × 25 pixels. Creator blocks are 50 × 50. Brand blocks are 100 × 100 and run as featured auctions.'],['Buy now, or place a bid','Community and Creator blocks have fixed prices. Brand auctions last 48 hours, one at a time. Bids are free, and a bid is not a payment.'],['Make it yours','Pay once for a 12-month placement. Auction winners finish checkout from My Pixels within 24 hours. Your placement starts after confirmed payment.'],['Tell your story','Submit a title, website and image. After review, your ad appears on the wall and in the readable Discover directory. Edits are reviewed too.'],['Watch the wall grow','The progress bar counts paid pixel area. A large block contributes more area than a small one. Bids and abandoned checkouts never inflate revenue.']].map(([t,c],i)=>`<div class="step"><span class="step-number">0${i+1}</span><div><h3>${t}</h3><p>${c}</p></div></div>`).join('')}</section><aside class="stack"><div class="note-card pink"><h3>Why “Auction”?</h3><p>The big brand spaces are the main event. Buy Now gives individuals an easy way to join, while the featured auction brings the friendly competition.</p></div><div class="note-card"><h3>How does the project earn?</h3><p>All spaces are sold by the site owner. Revenue comes from placement sales and winning bids. There are no buyer bidding fees, wallets or resale commissions.</p></div><div class="note-card"><h3>Will my ad get clicks?</h3><p>There is no guaranteed traffic, ranking, revenue or return. Buy a placement because you want to be part of the wall.</p></div></aside></div><div class="section-heading"><h2>A few good questions.</h2></div>${[['Can I try it without paying?','Yes. This entire review edition runs in your browser. Demo checkout uses no card details and makes no real charge.'],['What if a winner never pays?','Their 24-hour reservation expires and the block returns to the queue. It is not counted as sold, and the next bidder is not automatically charged.'],['Can I change my image later?','Yes. Paid owners can submit edits for review. The previous approved ad stays recorded while an edit is pending.'],['Can a company buy a bigger piece?','The 100 × 100 brand blocks are 16 times the area of a community block. Larger custom placements can be considered later without changing existing owners’ blocks.'],['Does it stay up forever?','The proposed launch offer is 12 months from payment, with no automatic renewal. A permanent placement is not promised.']].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}`;}
function rulesPage(){return `${pageHead('A GOOD WALL NEEDS GOOD NEIGHBORS','Clear rules. Less guesswork.','These are the proposed operating rules for the next edition. Live sales remain closed pending payment eligibility and launch preparation.') }<div class="two-col"><article class="content-card"><h3>Placement & auctions</h3><ul><li>One payment buys 12 months of ad placement, starting at confirmed payment. No automatic renewal.</li><li>Community: AED 20. Creator: AED 100. Brand auction opening bid: AED 500. Proposed prices are in AED.</li><li>A bid must increase the current price by at least 10%, rounded up to a whole dirham. The first bid may equal the opening price.</li><li>A bid in the last 60 seconds extends the auction to 60 seconds remaining, up to a maximum of 10 extra minutes.</li><li>Winners have 24 hours to pay. Unpaid blocks return to the queue. Runner-up bidders are never automatically charged.</li><li>No fake bids, self-bidding by the owner, bought followers, guaranteed returns, or off-site payment requests.</li><li>A paid placement buys space, not ownership of the website or a tradeable asset.</li></ul><h3 style="margin-top:25px">Advertising policy</h3><ul><li>Only submit content and images you have the right to use.</li><li>No phishing, malware, impersonation, hate, adult material, unlawful products, or misleading investment claims.</li><li>Ads and edits require approval. HTTPS links only. Visitors see the destination before leaving.</li><li>Links can change after approval. Reports trigger review; approval is not a guarantee that an advertiser is trustworthy.</li><li>Rejected content can be revised. Before live launch, publish a refund policy covering rejected ads, cancellations and failed delivery.</li></ul></article><aside class="stack"><article class="content-card"><h3>Privacy in this preview</h3><p>Demo names, bids, ads and reports are saved in localStorage on this browser. They are not shared between visitors and are not synced to Firebase. Reset demo clears them.</p><p>No real sign-in, card details or email addresses are collected. Google Fonts may receive a network request to deliver the typefaces.</p><p>Do not put sensitive or confidential information into the demo. A live version needs a privacy notice identifying its operator and service providers.</p></article><article class="content-card"><h3>Before real payments open</h3><p>The operator must connect an eligible payment account, deploy and test server-side ownership and bid enforcement, publish their business/contact and refund details, and confirm applicable licence and tax requirements.</p><p>Any fee shown in the Owner Studio calculator is an editable planning assumption, not a payment-provider quote.</p></article></aside></div>`;}
function studioPage(){const s=stats(state),pending=state.lots.filter(l=>l.status==='review'),a=activeAuction();return `${pageHead('THE OWNER’S DESK · LOCAL DEMO','Less admin. More building.','A sample control room for reviewing ads, handling reports and preparing your daily update. This demo studio is visible to everyone; a live studio must enforce admin access on the server.') }<div class="notice pink"><strong>Live payments: closed.</strong> No provider is connected. This review edition cannot take money. The production launch checklist is included in the source handoff.</div><div class="two-col"><div class="stack"><section class="content-card"><h3>Daily publishing</h3><p>Paid area: <strong>${s.percent.toFixed(2)}%</strong> · confirmed demo sales: <strong>${amount(s.gross)}</strong> gross. Outstanding bids stay outside this number.</p><div class="list-inline">${action('Copy daily update','copy-progress','','small dark')}<a class="button small ghost" href="#journey">Public journal ↗</a>${action('Download demo records','export','','small ghost')}</div></section><section class="content-card"><h3>Featured auction</h3>${a?`<p>${escape(a.id)} · ${statusText(a.status)} · ${amount(a.amount)}</p>${a.status==='active'?action('End sample auction now','end-auction',a.id,'small dark'):`<p>Waiting for winner payment until ${new Date(a.deadline).toLocaleString('en-GB',{timeZone:'Asia/Dubai'})} Dubai time.</p>${action('Simulate missed deadline','expire-winner',a.id,'small ghost')}`}`:`<p>There is no featured auction. Start the next brand block when you are ready.</p>${action('Open next sample auction','start-demo',state.lots.find(l=>l.status==='upcoming')?.id||'','small dark')}`}<p>These time controls are for testing. Real auction schedules and payment expiries must run on a trusted backend.</p></section><section class="content-card"><h3>Ad review queue · ${pending.length}</h3>${pending.length?pending.map(l=>`<div class="ad-review-preview"><div class="chip">${escape(l.id)}</div><h3 style="margin:12px 0 5px">${escape(l.pendingAd.title)}</h3><p>${escape(l.pendingAd.description)}</p><p class="mono" style="font-size:11px;overflow-wrap:anywhere">${escape(l.pendingAd.url)}</p>${l.pendingAd.image?`<img src="${l.pendingAd.image}" alt="Submitted ad preview">`:''}<p>Owner: ${escape(l.ownerName)}</p><div class="list-inline">${action('Approve demo ad','approve',l.id,'small dark')}${action('Return for revision','reject',l.id,'small ghost')}</div></div>`).join(''):'<p>No ads waiting. Submit a demo ad from My Pixels to try the review flow.</p>'}</section><section class="content-card"><h3>Reports · ${state.reports.filter(r=>!r.resolved).length} open</h3>${state.reports.length?state.reports.map((r,i)=>`<div class="ad-review-preview"><strong>${escape(r.id)} · ${escape(r.reason)}</strong><p>${escape(r.note||'No further details supplied.')}</p><p class="mono" style="font-size:10px">${r.resolved?'Resolved':'Needs review'} · ${ago(r.at)}</p>${!r.resolved?`<div class="list-inline">${action('Hide ad','hide-ad',r.id,'small dark')}${action('Resolve report','resolve-report',String(i),'small ghost')}</div>`:''}</div>`).join(''):'<p>No reports. Visitors can report a published ad from its profile.</p>'}</section></div><aside class="stack"><section class="content-card"><h3>Could the numbers work?</h3><p>Full inventory at proposed prices and opening bids produces <strong>AED 38,000 gross</strong>. That assumes every block sells; it is not a forecast.</p><div class="form-group"><label for="sell-through">SELL-THROUGH ASSUMPTION</label><input id="sell-through" type="range" min="0" max="100" value="100"><small id="sell-through-value">100% sold, proportionally across tiers</small></div><div class="inline-form"><div class="form-group"><label for="fee-percent">PROCESSING %</label><input id="fee-percent" type="number" min="0" max="20" step="0.1" value="2.9"></div><div class="form-group"><label for="fee-fixed">AED / PAYMENT</label><input id="fee-fixed" type="number" min="0" max="20" step="0.1" value="1"></div></div><div class="inline-form"><div class="form-group"><label for="refund-percent">REFUND RESERVE %</label><input id="refund-percent" type="number" min="0" max="100" value="5"></div><div class="form-group"><label for="annual-hosting">ANNUAL HOSTING AED</label><input id="annual-hosting" type="number" min="0" max="100000" value="0"></div></div><div id="economics"></div><p style="font-size:11px">Planning assumptions only. Excludes licence costs, taxes, your time, disputes, ad creation and other overhead. Processing fees may remain payable on refunds. Auction upside is excluded.</p></section><article class="note-card"><div class="eyebrow">ONE MILLION PIXELS, EXACTLY</div><h3>940 useful placements.</h3><p>800 community × 625 pixels<br>120 creator × 2,500 pixels<br>20 brand × 10,000 pixels<br><br>500,000 + 300,000 + 200,000 = 1,000,000 pixels.</p></article><article class="note-card pink"><h3>No manual payment claims.</h3><p>In production, only a verified provider event or server-side provider lookup may mark an order paid. A browser button, screenshot or redirect must never transfer ownership.</p></article></aside></div>`;}
function calculate(){const el=$('#economics');if(!el)return;const val=id=>Math.max(0,Number($(id).value)||0),fraction=Math.min(100,val('#sell-through'))/100,estimate=estimateRevenue(Math.min(20,val('#fee-percent')),Math.min(20,val('#fee-fixed')),Math.min(100,val('#refund-percent')),val('#annual-hosting'));const gross=estimate.gross*fraction,fees=estimate.processing*fraction,refunds=estimate.refunds*fraction,total=gross-fees-refunds-estimate.hosting;$('#sell-through-value').textContent=`${Math.round(fraction*100)}% sold, proportionally across tiers`;el.innerHTML=`<div class="summary-row"><span>Gross placement sales</span><strong>${amount(gross)}</strong></div><div class="summary-row"><span>Estimated processing</span><span>− ${amount(fees)}</span></div><div class="summary-row"><span>Refund reserve</span><span>− ${amount(refunds)}</span></div><div class="summary-row"><span>Annual hosting</span><span>− ${amount(estimate.hosting)}</span></div><div class="summary-row total"><span>Before other costs</span><span>${amount(total)}</span></div>`;}
function render(){headerUpdate();const pages={wall:wallPage,auctions:auctionsPage,directory:directoryPage,dashboard:dashboardPage,journey:journeyPage,how:howPage,rules:rulesPage,studio:studioPage,plans:wallPage};main.innerHTML=(pages[route()]||wallPage)();paintWall();directoryResults();calculate();if(route()==='plans')requestAnimationFrame(()=>$('#plans')?.scrollIntoView());}

function lotDialog(id){const l=find(id),t=TIERS[l.tier],ad=l.status==='published'?l.ad:null;modalOpen(`${t.name.toUpperCase()} BLOCK · ${l.id}`,`<h2 id="modal-title">${escape(ad?.title||`${t.name}, with room for you.`)}</h2>${pill(statusText(l.status),l.status==='published'?'lime':'')}<div class="lot-detail-art" style="background:${ad?.color||t.color};color:${contrast(ad?.color||t.color)}">${ad?.image?`<img src="${ad.image}" alt="${escape(ad.title)}">`:escape(ad?.title||`${l.side} × ${l.side}`)}</div>${ad?`<p>${escape(ad.description)}</p><p>Placed by ${escape(l.ownerName)} · ${l.side} × ${l.side} pixels.</p><div class="dialog-actions">${action('Report this ad','report',id,'small ghost')}${action('Visit website ↗','visit',id,'dark')}</div>`:`<p>${t.description} Every published ad also has a readable Discover profile.</p><div class="summary-row"><span>Placement</span><strong>${l.side} × ${l.side} pixels</strong></div><div class="summary-row"><span>${t.mode==='auction'?'Opening / current bid':'One-time price'}</span><strong>${amount(l.amount)}</strong></div><div class="summary-row"><span>Duration</span><strong>12 months after payment</strong></div><div class="dialog-actions">${l.status==='available'?action('Try demo checkout ↗','buy',id,'dark'):l.tier==='brand'&&!l.paidAt?action('Explore the auction ↗','go-auctions','','dark'):l.owner===state.user?.id?action('Edit my ad ↗','edit-ad',id,'dark'):'<p>This space is currently reserved or claimed.</p>'}</div>`}`,'lot');}
function buyDialog(id,resume=false){loginThen(()=>run(()=>{const l=resume?find(id):reserve(state,id);if(resume&&(l.reservedBy!==state.user.id||l.status!=='reserved'||l.deadline<=Date.now()))throw Error('This checkout has expired.');save();checkoutLot=id;checkoutDialog(l);}));}
function checkoutDialog(l){modalOpen('DEMO CHECKOUT · NO REAL PAYMENT',`<h2 id="modal-title">Your corner is waiting.</h2><p>${TIERS[l.tier].name} block ${escape(l.id)} · ${l.side} × ${l.side} pixels.</p><div class="summary-row"><span>12-month placement</span><strong>${amount(l.amount)}</strong></div><div class="summary-row"><span>Renewal</span><span>No automatic renewal</span></div><div class="summary-row total"><span>Demo total</span><span>${amount(l.amount)}</span></div><div class="checkout-lock"><strong>No card details. No real charge.</strong><p>Live payments are not connected. The button below simulates a confirmed payment to let you test the complete ownership and ad flow.</p></div><form id="checkout-form" data-id="${l.id}"><label class="check-label"><input name="terms" type="checkbox" required><span>I understand this is a local demo. The proposed offer is 12 months of placement, subject to ad approval, with no guarantee of traffic or returns.</span></label><div class="dialog-actions">${action('Cancel','close','','ghost')}<button class="button dark" type="submit">Simulate payment success ↗</button></div></form><p style="font-size:11px">Reservation expires in <span data-countdown="${l.deadline}">${remaining(l.deadline)}</span>.</p>`,'checkout');}
function bidDialog(id){loginThen(()=>run(()=>{const l=find(id);if(l.status!=='active')throw Error('This auction is closed.');const min=minimumBid(l);modalOpen('FEATURED AUCTION · DEMO BID',`<h2 id="modal-title">Make your next move.</h2><p>100 × 100 brand block ${escape(id)}. Current ${l.bids.length?'highest bid':'opening price'}: <strong>${amount(l.amount)}</strong>.</p><form id="bid-form" data-id="${id}"><div class="form-group"><label for="bid-amount">YOUR BID IN AED</label><input id="bid-amount" name="bid" type="number" min="${min}" max="1000000" step="1" value="${min}" required><small>Minimum ${money(min)}. At least 10% above the current bid after the first bid.</small></div><label class="check-label"><input type="checkbox" name="confirm" required><span>If I win, I will have 24 hours to complete checkout. This demo does not charge a card.</span></label><div class="notice blue">A bid is a commitment to the displayed amount. Your bid cannot be retracted in this preview.</div><button class="button dark full" type="submit">Confirm demo bid ↗</button></form>`,'bid');}));}
function editDialog(id){run(()=>{const l=find(id);if(l.owner!==state.user?.id||!l.paidAt)throw Error('Only the paid owner can edit this ad.');const ad=l.pendingAd||l.ad||{title:'',description:'',url:'',color:'#2935a3',image:null};uploadedImage=ad.image;modalOpen(`YOUR AD · ${id}`,`<h2 id="modal-title">A small spot. Your big idea.</h2><p>Your ad appears after approval. Use an image you own and a safe HTTPS destination.</p><form id="ad-form" data-id="${id}"><div class="form-group"><label for="ad-title">PROJECT / AD TITLE</label><input id="ad-title" name="title" required minlength="2" maxlength="40" value="${escape(ad.title)}" placeholder="Studio Luna"></div><div class="form-group"><label for="ad-description">YOUR SHORT INTRODUCTION</label><textarea id="ad-description" name="description" maxlength="160" placeholder="What are you making? Who is it for?">${escape(ad.description)}</textarea></div><div class="form-group"><label for="ad-url">WEBSITE ADDRESS</label><input id="ad-url" name="url" type="url" required value="${escape(ad.url)}" placeholder="https://example.com"></div><div class="inline-form"><div class="form-group"><label for="ad-color">BACKGROUND COLOR</label><input id="ad-color" name="color" type="color" value="${ad.color}"></div><div class="form-group"><label for="ad-image">OPTIONAL IMAGE</label><input id="ad-image" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP. Maximum 5 MB input; resized locally to 256 px.</small></div></div><div id="image-preview" ${ad.image?'':'hidden'}>${ad.image?`<img src="${ad.image}" alt="Selected ad image" style="max-height:100px;max-width:100%">`:''}</div><button type="button" class="tab" data-action="remove-image">Remove image</button><div class="form-group"><label class="check-label"><input name="rights" type="checkbox" required><span>I have permission to use this content, and it follows the <a href="#rules">wall rules</a>.</span></label></div><button class="button dark full" type="submit">Submit ad for review ↗</button></form>`,'ad');});}
function reportDialog(id){modalOpen('KEEP THE WALL SAFE',`<h2 id="modal-title">Something doesn’t look right?</h2><p>Report block ${escape(id)} for review. Demo reports appear in the local Owner Studio.</p><form id="report-form" data-id="${escape(id)}"><div class="form-group"><label for="report-reason">REASON</label><select id="report-reason" name="reason"><option>Suspicious or misleading link</option><option>Impersonation</option><option>Copyright or content rights</option><option>Inappropriate content</option><option>Other</option></select></div><div class="form-group"><label for="report-note">OPTIONAL DETAILS</label><textarea id="report-note" name="note" maxlength="400" placeholder="Please do not include private information."></textarea></div><button type="submit" class="button dark full">Submit demo report</button></form>`,'report');}
function visitDialog(id){const ad=find(id).ad,u=safeUrl(ad?.url);if(!u)throw Error('This link is unavailable.');modalOpen('YOU ARE LEAVING THE WALL',`<h2 id="modal-title">Meet ${escape(ad.title)}.</h2><p>This is an independent advertiser’s website. Ad approval does not guarantee the safety or claims of the destination.</p><div class="notice mono" style="overflow-wrap:anywhere">${escape(u)}</div><div class="dialog-actions">${action('Stay here','close','','ghost')}<a class="button dark" href="${escape(u)}" target="_blank" rel="noopener noreferrer nofollow sponsored">Continue to website ↗</a></div>`);}
async function copyProgress(){const s=stats(state),day=state.campaignStart?Math.floor((Date.now()-state.campaignStart)/86400000)+1:0,text=`Day ${day} of filling the Million Pixel Auction.\n${s.percent.toFixed(2)}% filled. ${s.paidLots} corners claimed.\n${s.paidPixels.toLocaleString()} / 1,000,000 pixels.\nCollected: ${money(s.gross)} gross (DEMO, not real sales).\nWho should claim the next spot?`;try{await navigator.clipboard.writeText(text);toast('Demo daily update copied.');}catch{modalOpen('DAILY UPDATE',`<h2 id="modal-title">Your update, ready to copy.</h2><textarea class="search-input" style="width:100%;max-width:100%;height:170px" readonly>${escape(text)}</textarea>`);}}
function exportRecords(){const blob=new Blob([JSON.stringify({...state,user:state.user?{name:state.user.name,id:state.user.id}:null,warning:'LOCAL DEMO DATA. NOT REAL SALES.'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='million-pixel-demo-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Demo records downloaded.');}

document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;const {action:act,id}=btn.dataset;run(()=>{switch(act){case 'close':modalClose();break;case 'lot':lotDialog(id);break;case 'profile':profileDialog();break;case 'switch-user':{const after=returnAction;state.user={id,name:id==='alex'?'Alex':'Sam'};modalClose();commit(`Demo profile switched to ${state.user.name}.`);returnAction=null;after?.();break;}case 'sign-out':modalClose();state.user=null;commit('Signed out of the local demo.');break;case 'reset-confirm':checkoutLot=null;state=freshState();zoom=1;search='';modalClose();commit('A fresh demo canvas is ready.');break;case 'wall-filter':wallFilter=id;render();break;case 'directory-filter':directoryFilter=id;render();break;case 'zoom-in':zoom=Math.min(4,zoom+.5);render();break;case 'zoom-out':zoom=Math.max(1,zoom-.5);render();break;case 'pick-tier':if(route()!=='wall')location.hash='wall';wallFilter=id;render();requestAnimationFrame(()=>$('#wall-scroll')?.scrollIntoView({block:'center'}));lotDialog(state.lots.find(l=>l.tier===id&&l.status==='available')?.id||state.lots.find(l=>l.tier===id).id);break;case 'go-auctions':modalClose();location.hash='auctions';break;case 'buy':buyDialog(id);break;case 'resume-checkout':buyDialog(id,true);break;case 'pay-winner':loginThen(()=>{const l=find(id);if(l.winner!==state.user.id||l.status!=='awaiting-payment')throw Error('This winning checkout belongs to another profile.');checkoutLot=null;checkoutDialog(l);});break;case 'bid':bidDialog(id);break;case 'edit-ad':editDialog(id);break;case 'start-demo':if(!id)throw Error('No brand blocks remain in the queue.');startAuction(state,id);modalClose();commit('Sample auction opened for 48 hours.');location.hash='auctions';break;case 'end-auction':{const l=find(id);l.endsAt=Date.now()-1;expire(state);commit('Sample auction ended. Unpaid wins do not count as sales.');break;}case 'expire-winner':find(id).deadline=Date.now()-1;expire(state);commit('Unpaid winner expired. The brand block is back in the queue.');break;case 'approve':approveAd(state,id);commit('Demo ad approved and published.');break;case 'reject':rejectAd(state,id);commit('Ad returned to the owner for revision.');break;case 'report':reportDialog(id);break;case 'visit':visitDialog(id);break;case 'hide-ad':find(id).status='hidden';commit('Ad hidden from the public wall and directory.');break;case 'resolve-report':state.reports[Number(id)].resolved=true;commit('Report marked resolved.');break;case 'copy-progress':copyProgress();break;case 'export':exportRecords();break;case 'remove-image':uploadedImage=null;$('#image-preview').innerHTML='';$('#image-preview').hidden=true;$('#ad-image').value='';break;}});});
document.addEventListener('submit',e=>{if(!e.target.matches('#profile-form,#checkout-form,#bid-form,#ad-form,#report-form'))return;e.preventDefault();const form=e.target,data=new FormData(form),id=form.dataset.id;try{if(form.id==='profile-form'){const name=String(data.get('name')).trim();if(name.length<2||name.length>24)throw Error('Use a name between 2 and 24 characters.');const after=returnAction;state.user={id:state.user?.id||crypto.randomUUID(),name};modalClose();returnAction=null;commit('Your local demo profile is ready.');after?.();}else if(form.id==='checkout-form'){simulatePayment(state,id);checkoutLot=null;modalClose();commit('Demo payment confirmed. Your block is ready for an ad.');if(route()==='dashboard')editDialog(id);else{afterNavigation=()=>editDialog(id);location.hash='dashboard';}}else if(form.id==='bid-form'){placeBid(state,id,Number(data.get('bid')));modalClose();commit('Demo bid placed. Track your status in My Pixels.');}else if(form.id==='ad-form'){submitAd(state,id,{title:String(data.get('title')),description:String(data.get('description')),url:String(data.get('url')),color:String(data.get('color')),image:uploadedImage});modalClose();commit('Submitted for review. Try approving it in the demo Owner Studio.');}else if(form.id==='report-form'){if(state.reports.some(r=>r.id===id&&!r.resolved))throw Error('This block already has an open report in this demo.');state.reports.unshift({id,reason:String(data.get('reason')),note:String(data.get('note')).slice(0,400),at:Date.now(),resolved:false});modalClose();commit('Demo report submitted. Find it in the Owner Studio.');}}catch(err){let error=form.querySelector('.error');if(!error){error=document.createElement('div');error.className='error';error.setAttribute('role','alert');form.prepend(error);}error.textContent=err.message;}});
document.addEventListener('input',e=>{if(e.target.id==='directory-search'){search=e.target.value;directoryResults();}if(['sell-through','fee-percent','fee-fixed','refund-percent','annual-hosting'].includes(e.target.id))calculate();});
document.addEventListener('change',async e=>{if(e.target.id!=='ad-image')return;const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Choose a PNG, JPEG or WebP image under 5 MB.');const image=await createImageBitmap(file);const scale=Math.min(1,256/Math.max(image.width,image.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(image.width*scale));c.height=Math.max(1,Math.round(image.height*scale));c.getContext('2d').drawImage(image,0,0,c.width,c.height);image.close();const imageData=c.toDataURL('image/webp',.8);if(imageData.length>190000)throw Error('That image is too complex. Try a simpler image.');if(activeDialog!=='ad')return;uploadedImage=imageData;$('#image-preview').hidden=false;$('#image-preview').innerHTML=`<img src="${uploadedImage}" alt="Selected ad image" style="max-height:100px;max-width:100%">`;toast('Image resized and ready.');}catch(err){e.target.value='';toast(err.message);}});
setInterval(()=>{if(expire(state)){save();if(modal.open){checkoutLot=null;modalClose();toast('A reservation or auction deadline changed. Please check its current status.');}render();}document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=remaining(Number(el.dataset.countdown)));},1000);
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){checkoutLot=null;modal.close();load();render();toast('Demo activity updated from another tab.');}});
render();

